import type { FC, ReactChild } from 'react';
import React from 'react';

import type { EditorPlugins } from './../ricos-plugins/index.js';

interface PluginsContextProps {
  plugins: EditorPlugins;
  children: ReactChild;
}

export const PluginsContext = React.createContext<EditorPlugins>(null as unknown as EditorPlugins);

export const PluginsContextProvider: FC<PluginsContextProps> = ({ plugins, children }) => (
  <PluginsContext.Provider value={plugins}>{children}</PluginsContext.Provider>
);
