import { Divider } from '@wix/design-system';
import cx from 'classnames';
import React, { useContext } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';

import classes from './toolbar-button-separator-scss.js';

/**
 * Vertical rule between toolbar button groups.
 *
 * The ricos element stays and WDS `Divider` renders inside it, rather than replacing it: a vertical
 * `Divider` is `min-height: 100%`, so on its own it takes the height of whatever contains it. In a
 * plugin toolbar that container is 30px, which would stretch a line that is deliberately 12px.
 * Keeping the wrapper is what pins the height — and the rule that would otherwise have to be
 * outranked is `.wds_<version>_Divider__root.wds_<version>_Divider---direction-8-vertical`,
 * specificity (0,2,0), whose Stylable namespace embeds the WDS version and therefore rots.
 */
export const ToolbarButtonSeparator = () => {
  const { isMobile } = useContext(RicosContext);

  return (
    <div className={cx(classes.separator, { [classes.mobileSeparator]: isMobile })}>
      <Divider direction="vertical" />
    </div>
  );
};
