import type { DropdownLayoutOption } from '@wix/design-system';
import {
  DropdownBase,
  ListItemSection,
  SidePanel,
  listItemSectionBuilder,
} from '@wix/design-system';
import Fuse from 'fuse.js';
import React, {
  forwardRef,
  useContext,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
} from 'react';

import {
  EditorContext,
  PluginsContext,
  RicosContext,
  ZIndexContext,
} from './../../../ricos-context/index.js';
import type { ModalService } from './../../../ricos-modals/index.js';
import { useModalService } from './../../../ricos-modals/modal-service-provider.js';
import type { TFunction } from './../../../ricos-types/common-types.js';
import type { PublicCommands } from './../../../ricos-types/editor-commands-type.js';
import { Node_Type } from './../../../ricos-types/index.js';
import type { QuickAction } from './../../../ricos-types/plugin-types.js';
import { quickActionsModalSections } from './../../../ricos-types/plugin-types.js';
import type { LogBiFn } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { ListItemDivider } from './../../../_shared/list-item-divider/list-item-divider.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';
import type { Editor } from './../../../tiptap/core/index.js';
import { UiComponentsProvider } from './../../../ui-components/index.js';

import { QUICK_ACTIONS_ROOT } from '../data-hooks.js';
import type { QuickActionsModalProps, QuickActionsModalRef } from '../types.js';
import { QUICK_ACTIONS_MODAL_ID } from '../types.js';
import styles from './modal-scss.js';

const COMMONLY_USED: string[] = [
  'pageBreak',
  'writeWithAi',
  Node_Type.IMAGE,
  Node_Type.GALLERY,
  Node_Type.BUTTON,
  `${Node_Type.VIDEO}.youTube`,
];

export const QuickActionsModal = forwardRef<QuickActionsModalRef, QuickActionsModalProps>(
  (props, ref) => {
    const { query, supportedPlugins } = props;

    const { adapter, getPublicCommands } = useContext(EditorContext);
    const plugins = useContext(PluginsContext);
    const { t, isMobile } = useContext(RicosContext);
    const zIndexService = useContext(ZIndexContext);
    const actions = useMemo(() => {
      const quickActionPlugins = plugins.getQuickActions();
      const editor = adapter.tiptapEditor;

      const filteredBySupport = supportedPlugins?.length
        ? quickActionPlugins.filter(action => supportedPlugins.includes(action.id))
        : quickActionPlugins;

      // Allow each action to opt out for the current selection. Evaluated once
      // when the modal opens (selection is fixed at that point).
      return filteredBySupport.filter(action =>
        action.isVisible ? action.isVisible(editor) : true
      );
    }, [plugins, supportedPlugins, adapter]);
    const [refElement, setRefElement] = useState<HTMLDivElement | null>(null);
    const logBi = useBiNext({ modalId: QUICK_ACTIONS_MODAL_ID });
    const latestOptionsRef = useRef<DropdownLayoutOption[]>([]);
    const latestSelectedIdRef = useRef<string | number | undefined>(undefined);

    const modalService = useModalService();
    const publicCommands = getPublicCommands();

    const options = useMemo(() => {
      const filtered = filterActions(actions, query || '', t);

      const actionsInSectionsMap = filtered.reduce(
        (groups, action) => {
          if (!query && COMMONLY_USED.includes(action.id)) {
            groups[quickActionsModalSections.CommonlyUsed] ??= [];
            groups[quickActionsModalSections.CommonlyUsed].push(action);
          }

          groups[action.section] ??= [];

          return {
            ...groups,
            [action.section]: [...groups[action.section], action],
          };
        },
        {} as { [key: string]: QuickAction[] }
      );

      actionsInSectionsMap[quickActionsModalSections.CommonlyUsed]?.sort(
        (a, b) => COMMONLY_USED.indexOf(a.id) - COMMONLY_USED.indexOf(b.id)
      );

      const quickActionOptionProps = {
        publicCommands,
        props,
        modalService,
        t,
        editor: adapter.tiptapEditor,
        logBi,
      };

      const organizedOptions = !query
        ? Object.values(quickActionsModalSections).reduce<DropdownLayoutOption[]>(
            (list, section) => {
              return [
                ...list,

                ...(actionsInSectionsMap[section]?.length > 0
                  ? createSection({
                      items: actionsInSectionsMap[section],
                      section,
                      ...quickActionOptionProps,
                    })
                  : []),
              ];
            },
            []
          )
        : Object.entries(actionsInSectionsMap).reduce<DropdownLayoutOption[]>(
            (list, [section, items]) => {
              return [
                ...list,
                ...(items.length > 0
                  ? createSection({
                      items,
                      section,
                      ...quickActionOptionProps,
                    })
                  : []),
              ];
            },
            []
          );

      if (organizedOptions[organizedOptions.length - 1]?.id === '-') {
        organizedOptions.pop();
      }
      return organizedOptions;
    }, [query]);

    const [selectedId, setSelectedId] = useState(
      options.find(option => option.value === 'action')?.id
    );

    const [open, setOpen] = useState(false);
    const currElement: React.MutableRefObject<null | DropdownBase> = useRef(null);

    useEffect(() => {
      setSelectedId(options.find(option => option.value === 'action')?.id);
      setOpen(!!options.length);
    }, [query]);

    useEffect(() => {
      latestOptionsRef.current = options;
      latestSelectedIdRef.current = selectedId;
    }, [options.length, query, selectedId]);

    useImperativeHandle(
      ref,
      () => ({
        onKeyDown: ({ event }: { event: KeyboardEvent }) => {
          if (!latestOptionsRef.current || latestOptionsRef.current.length === 0) {
            return false;
          }
          if (['ArrowUp', 'ArrowDown'].includes(event.key)) {
            const direction = event.key === 'ArrowUp' ? -1 : 1;
            const activeOptions = latestOptionsRef.current.filter(
              option => option.value === 'action'
            );

            if (!activeOptions.length) {
              return false;
            }
            setSelectedId(prev => {
              const currIndex = activeOptions.findIndex(({ id }) => id === prev);
              const nextIndex =
                (currIndex + direction + activeOptions.length) % activeOptions.length;
              return activeOptions[nextIndex].id;
            });
            return true;
          }
          if (['Enter', 'Tab'].includes(event.key)) {
            const option = latestOptionsRef.current.find(
              option => option.id === latestSelectedIdRef.current
            );
            if (option && 'onClick' in option) {
              option?.onClick?.();
              return true;
            }
            return false;
          }
          return false;
        },
      }),
      [query, latestOptionsRef.current.length, options.length, selectedId]
    );

    if (isMobile) {
      return (
        <SidePanel
          closeButtonProps={{ onClick: () => modalService.closeModal(QUICK_ACTIONS_MODAL_ID) }}
          width="100%"
          maxHeight="50vh"
          height="fit-content"
        >
          <SidePanel.Header title={t('QuickActionsPlugin_Modal_Header_Title')} />
          <SidePanel.Content className={styles.mobileContent}>
            {options.map((option, index) => {
              if (option.id === '-') {
                return <ListItemDivider key={option.id + index} />;
              }

              if ('optionTitle' in option && option.optionTitle) {
                return (
                  <ListItemSelect
                    key={option.id}
                    title={option.optionTitle}
                    prefix={option.prefix}
                    onSelect={option.onClick}
                  />
                );
              }

              return <ListItemSection key={option.id} title={t(option.id?.toString() ?? '')} />;
            })}
          </SidePanel.Content>
        </SidePanel>
      );
    }

    return (
      <div
        className={styles.quickActionsModal}
        style={{ zIndex: zIndexService.getZIndex('DIALOG') }}
        ref={setRefElement}
      >
        {refElement && (
          <UiComponentsProvider containerEl={refElement}>
            <DropdownBase
              ref={currElement}
              open={open}
              placement="bottom-start"
              minWidth={280}
              maxHeight={250}
              className={styles.quickActionsModal}
              // oxlint-disable-next-line jsx-a11y/no-autofocus
              autoFocus={false}
              focusOnOption={selectedId}
              dataHook={QUICK_ACTIONS_ROOT}
              options={options}
              listType="action"
            />
          </UiComponentsProvider>
        )}
      </div>
    );
  }
);

type QuickActionOptionProps = {
  section: string;
  publicCommands: PublicCommands;
  props: QuickActionsModalProps;
  modalService: ModalService;
  t: TFunction;
  logBi: LogBiFn;
  editor: Editor;
};

type Option = {
  as: string;
  dataHook: string;
  ellipsis: boolean;
  id: string;
  onClick: () => void;
  optionTitle: string;
  // There is a type mismatch between DropdownLayoutOption and Option.
  // Since DropdownBase internally uses listItemActionBuilder, we need to provide prefixIcon accordingly.
  // You can trace the relevant WDS internals here:
  // https://github.com/wix-private/wix-design-systems/blob/a84540d33d86f74045e45d09f90d285cc556be21/packages/wix-design-system/src/ListItemAction/ListItemAction.tsx#L180
  prefixIcon?: JSX.Element;
  prefix?: JSX.Element;
  shouldFocusWithoutScroll: boolean;
  size: string;
  title: boolean;
  value: string;
};

const commandToQuickActionOption = ({
  quickAction,
  publicCommands,
  props,
  editor,
  modalService,
  t,
  section,
  logBi,
}: QuickActionOptionProps & {
  quickAction: QuickAction;
}): Option => {
  return {
    as: 'button',
    dataHook:
      section === quickActionsModalSections.CommonlyUsed
        ? `${quickAction.id}${section}`
        : quickAction.id,
    ellipsis: false,
    id: `${quickAction.id}${section}`,
    onClick: () => {
      props?.command?.(props);
      quickAction.command({ publicCommands, editor, modalService });

      logBi({ dataHook: QUICK_ACTIONS_ROOT, value: quickAction.id });
      modalService.closeModal(QUICK_ACTIONS_MODAL_ID);
    },
    optionTitle: t(quickAction.title),
    prefixIcon: quickAction.icon ? <quickAction.icon /> : undefined,
    prefix: quickAction.icon ? <quickAction.icon /> : undefined,
    shouldFocusWithoutScroll: true,
    size: 'small',
    title: false,
    value: 'action',
  };
};

const createSection = ({
  items,
  section,
  t,
  ...rest
}: QuickActionOptionProps & {
  items: QuickAction[];
}) => {
  return [
    listItemSectionBuilder({
      title: t(section),
      id: section,
    }),

    ...items.map((item: QuickAction) =>
      commandToQuickActionOption({
        quickAction: item,
        section,
        t,
        ...rest,
      })
    ),

    listItemSectionBuilder({
      type: 'divider',
      id: '-',
    }),
  ];
};

const filterActions = (actions: QuickAction[], query: string, t: TFunction) => {
  if (!query) {
    return actions;
  }

  if (query.match(/^ /)?.length || (query.match(/ /gm)?.length || 0) > 1) {
    return [];
  }

  const queryIsSectionName = Object.values(quickActionsModalSections).find(
    val => t(val).toLowerCase() === query.toLowerCase()
  );
  if (queryIsSectionName) {
    return actions.filter(({ section }) => t(section).toLowerCase() === query.toLowerCase());
  }

  const fuse = new Fuse(actions, {
    keys: [
      { name: 'title', getFn: action => t(action.title), weight: 0.7 },
      { name: 'section', getFn: action => t(action.section), weight: 0.3 },
      { name: 'tags', getFn: action => action.tags.join(' '), weight: 0.2 },
    ],
    threshold: 0.4,
    minMatchCharLength: query.length > 1 ? 2 : 1,
  });

  const result = fuse.search(query);

  if (result.length) {
    return result.map(({ item }) => item);
  }

  return actions.filter(item => t(item.title).toLowerCase().includes(query.toLowerCase()));
};
