import type { Context } from 'react';
import React from 'react';

import { ModalServiceContext } from './../ricos-context/modal-context.js';
import type { ModalSettings } from './../ricos-types/ricos-types.js';
import type { SelectorContextValue } from './../_shared/use-context-selector.js';
import { createContext, useContextSelector } from './../_shared/use-context-selector.js';

import type { ModalState } from './modal-service.js';
import { ModalService } from './modal-service.js';

const ModalStateContext = createContext<ModalState>({});

// Whether an external (non-Ricos-rendered) modal-like flow — e.g. the host's
// Media Manager — is currently open. Kept separate from ModalStateContext
// because ModalRenderer renders a <ModalPopper> for every entry in that
// state; an external modal has no Component/props to render.
const ExternalModalOpenContext = React.createContext(false);

export const ModalProvider: React.FC<{
  modalSettings: ModalSettings | undefined;
  children: React.ReactNode;
}> = props => {
  const [modalState, setModalState] = React.useState<ModalState>({});
  const modalStateRef = React.useRef(modalState);
  modalStateRef.current = modalState;

  const [isExternalModalOpen, setIsExternalModalOpen] = React.useState(false);

  const [service] = React.useState(
    () =>
      new ModalService(
        props.modalSettings ?? {},
        {
          get: () => modalStateRef.current ?? {},
          set: setModalState,
        },
        { set: setIsExternalModalOpen }
      )
  );

  return (
    <ModalServiceContext.Provider value={service}>
      <ModalStateContext.Provider value={modalState}>
        <ExternalModalOpenContext.Provider value={isExternalModalOpen}>
          {props.children}
        </ExternalModalOpenContext.Provider>
      </ModalStateContext.Provider>
    </ModalServiceContext.Provider>
  );
};

export const useModalService = () => {
  const context = React.useContext(ModalServiceContext);
  if (!context) {
    throw new Error('useModalService must be used within a ModalProvider');
  }
  return context;
};

/** Reactive read of ModalService.notifyExternalModalOpened/Closed state. */
export const useIsExternalModalOpen = () => React.useContext(ExternalModalOpenContext);

export const useModalStateContext = ({
  onSelectorContextValue,
}: {
  onSelectorContextValue: (selectorContextValue: SelectorContextValue<ModalState>) => void;
}) => {
  const context = React.useContext(
    ModalStateContext as unknown as Context<SelectorContextValue<ModalState>>
  );
  if (!context) {
    throw new Error('useModalStateContext must be used within a ModalProvider');
  }
  onSelectorContextValue(context);
  return context;
};

export const useModalState = <T extends unknown>(
  selector: (s: ModalState) => T,
  trackingString?: string
): T => {
  return useContextSelector(ModalStateContext, selector, Object.is, trackingString);
};

export const getIsModalOpen = (id: string) => (state: ModalState) => !!state[id];
export const getIsAnyModalOpenByIdPrefix = (prefix: string) => (state: ModalState) =>
  Object.keys(state).some(id => id.startsWith(prefix));
export const getIsExclusiveModalOpen = (state: ModalState) =>
  Object.values(state).some(m => m.type === 'exclusive');
