import { Box, Divider, FieldSet, RadioGroup, SegmentedToggle, Text } from '@wix/design-system';
import { AlignLeft, AlignRight } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useRef } from 'react';

import {
  EditorContext,
  ModalServiceContext,
  PluginsEventsContext,
  RicosContext,
} from './../../ricos-context/index.js';
import { useBiNext } from './../../_shared/bi-context-provider/bi-context-provider.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import type { PmCollapsibleListNode } from './../../_shared/pm-node-types.js';
import { useNodeAttrs } from './../../_shared/use-node-attrs.js';
import {
  Panel,
  PanelHeader,
  ToggleButton,
  usePanelContainerElement,
} from './../../ui-components/index.js';

import { COLLAPSIBLE_LIST_SETTINGS_MODAL_ID } from '../consts.js';
import {
  SETTINGS_DIRECTION,
  SETTINGS_DIRECTION_LTR,
  SETTINGS_DIRECTION_RTL,
  SETTINGS_EXPAND_ONLY_ONE_TOGGLE,
  SETTINGS_INITIAL_EXPANDED,
  SETTINGS_INITIAL_EXPANDED_ALL,
  SETTINGS_INITIAL_EXPANDED_FIRST,
  SETTINGS_INITIAL_EXPANDED_NONE,
  SETTINGS_IS_QA_PAGE_TOGGLE,
  SETTINGS_MODAL,
} from '../data-hooks.js';
import classes from '../statics/styles/collapsible-list-settings-scss.js';
import { COLLAPSIBLE_LIST_TYPE, initialExpandedItems, listDirection } from '../types.js';

export type SettingsProps = {
  nodeId: string;
  isQapageDataEnabled: boolean;
};

export const CollapsibleListSettingsModal: FC<SettingsProps> = ({
  nodeId,
  isQapageDataEnabled,
}) => {
  const { t, environment } = useContext(RicosContext);
  const containerEl = usePanelContainerElement();
  const modalService = useContext(ModalServiceContext) || {};
  const { adapter } = useContext(EditorContext);
  const pluginsEvents = useContext(PluginsEventsContext);
  const tooltipRef = useRef<HTMLDivElement>(null);
  const logBi = useBiNext({
    pluginId: 'collapsibleList',
    modalId: COLLAPSIBLE_LIST_SETTINGS_MODAL_ID,
    nodeId,
  });
  const { pmNodeAttrs } = useNodeAttrs(nodeId, 'COLLAPSIBLE_LIST');

  if (!pmNodeAttrs) {
    logInvariant(new Error('Collapsible list settings: node attrs not found'));
    return null;
  }

  const handleChange = (attrs: Partial<PmCollapsibleListNode['attrs']>) => {
    adapter.tiptapEditor.commands.setCollapsibleListAttributes(nodeId, attrs);
  };

  const directionDataSource = [
    {
      value: listDirection.LTR,
      label: t('CollapsibleList_CollapsibleListSettings_Tab_Settings_Direction_LTR'),
      icon: <AlignLeft />,
      dataHook: SETTINGS_DIRECTION_LTR,
    },
    {
      value: listDirection.RTL,
      label: t('CollapsibleList_CollapsibleListSettings_Tab_Settings_Direction_RTL'),
      icon: <AlignRight />,
      dataHook: SETTINGS_DIRECTION_RTL,
    },
  ];

  return (
    <Panel
      onCloseButtonClick={() => modalService.closeModal(COLLAPSIBLE_LIST_SETTINGS_MODAL_ID)}
      dataHook={SETTINGS_MODAL}
    >
      <PanelHeader title={t('CollapsibleList_CollapsibleListSettings_Common_Header')} />

      <Box direction="vertical" gap="SP2" padding="SP3" overflow="auto">
        <Box paddingBottom="SP1">
          <Text size="small" weight="bold">
            {t('CollapsibleList_CollapsibleListSettings_Section_Settings_Title')}
          </Text>
        </Box>
        <FieldSet
          legend={t('CollapsibleList_CollapsibleListSettings_Tab_Settings_CollapseView_Title')}
          maxLines={3}
        >
          <RadioGroup
            value={pmNodeAttrs.initialExpandedItems}
            onChange={(changedValue?: string | number) => {
              handleChange({
                initialExpandedItems: changedValue as typeof pmNodeAttrs.initialExpandedItems,
                expandOnlyOne:
                  changedValue === initialExpandedItems.ALL ? false : pmNodeAttrs.expandOnlyOne,
              });

              logBi({
                dataHook: SETTINGS_INITIAL_EXPANDED,
                value:
                  changedValue === initialExpandedItems.ALL
                    ? SETTINGS_INITIAL_EXPANDED_ALL
                    : changedValue === initialExpandedItems.FIRST
                      ? SETTINGS_INITIAL_EXPANDED_FIRST
                      : SETTINGS_INITIAL_EXPANDED_NONE,
              });
            }}
          >
            <RadioGroup.Radio
              value={initialExpandedItems.ALL}
              dataHook={SETTINGS_INITIAL_EXPANDED_ALL}
            >
              <Text size="small">
                {t('CollapsibleList_CollapsibleListSettings_Tab_Settings_CollapseView_Expanded')}
              </Text>
            </RadioGroup.Radio>
            <RadioGroup.Radio
              value={initialExpandedItems.FIRST}
              dataHook={SETTINGS_INITIAL_EXPANDED_FIRST}
            >
              <Text size="small">
                {t(
                  'CollapsibleList_CollapsibleListSettings_Tab_Settings_CollapseView_FirstExpanded'
                )}
              </Text>
            </RadioGroup.Radio>
            <RadioGroup.Radio
              value={initialExpandedItems.NONE}
              dataHook={SETTINGS_INITIAL_EXPANDED_NONE}
            >
              <Text size="small">
                {t('CollapsibleList_CollapsibleListSettings_Tab_Settings_CollapseView_Collapsed')}
              </Text>
            </RadioGroup.Radio>
          </RadioGroup>
        </FieldSet>
        {pmNodeAttrs.initialExpandedItems !== initialExpandedItems.ALL && (
          <ToggleButton
            title={t(
              'CollapsibleList_CollapsibleListSettings_Tab_Settings_CollapseView_InSections'
            )}
            size="small"
            checked={pmNodeAttrs.expandOnlyOne}
            dataHook={SETTINGS_EXPAND_ONLY_ONE_TOGGLE}
            onChange={() => {
              const expandOnlyOne =
                pmNodeAttrs.initialExpandedItems === initialExpandedItems.ALL
                  ? false
                  : pmNodeAttrs.expandOnlyOne;
              handleChange({ expandOnlyOne: !expandOnlyOne });

              logBi({ dataHook: SETTINGS_EXPAND_ONLY_ONE_TOGGLE, value: expandOnlyOne });
            }}
          />
        )}
        {isQapageDataEnabled && environment !== 'wixel' && (
          <ToggleButton
            title={t('CollapsibleList_CollapsibleListSettings_Tab_Settings_FAQ_Enabled_Toggle')}
            tooltipAppendTo={containerEl}
            toolTipSize="small"
            infoContent={
              <div ref={tooltipRef} className={classes.tooltip}>
                {t('CollapsibleList_CollapsibleListSettings_Tab_Settings_FAQ_Enabled_Tooltip')}{' '}
                <a
                  href="https://support.wix.com/en/article/wix-blog-creating-an-faq-using-a-collapsible-list"
                  target="_blank"
                  rel="noreferrer"
                  className={classes.link}
                >
                  {t('LinkPanel_Learn_More_Label')}
                </a>
              </div>
            }
            size="small"
            checked={Boolean(pmNodeAttrs.isQapageData)}
            dataHook={SETTINGS_IS_QA_PAGE_TOGGLE}
            onChange={() => {
              pluginsEvents.publishPluginChangeSettings({
                pluginId: COLLAPSIBLE_LIST_TYPE,
                actionName: 'QapageData',
                value: pmNodeAttrs.isQapageData ? 'no' : 'yes',
                nodeId,
              });

              handleChange({ isQapageData: !pmNodeAttrs.isQapageData });

              logBi({
                dataHook: SETTINGS_IS_QA_PAGE_TOGGLE,
                value: pmNodeAttrs.isQapageData ?? false,
              });
            }}
          />
        )}
        <Box paddingTop="SP1">
          <Divider />
        </Box>
        <Box paddingBottom="SP1">
          <Text size="small" weight="bold">
            {t('CollapsibleList_CollapsibleListSettings_Section_Display_Title')}
          </Text>
        </Box>
        <FieldSet
          legend={t('CollapsibleList_CollapsibleListSettings_Tab_Settings_Direction_Title')}
          infoContent={t(
            'CollapsibleList_CollapsibleListSettings_Tab_Settings_Direction_Title_Tooltip'
          )}
          infoTooltipProps={{ size: 'small', appendTo: containerEl }}
        >
          <SegmentedToggle
            size={'small'}
            selected={pmNodeAttrs.direction}
            defaultSelected={pmNodeAttrs.direction}
            onClick={(_, direction) => {
              handleChange({ direction: direction as typeof pmNodeAttrs.direction });

              logBi({
                dataHook: SETTINGS_DIRECTION,
                value:
                  direction === listDirection.LTR ? SETTINGS_DIRECTION_LTR : SETTINGS_DIRECTION_RTL,
              });
            }}
          >
            {directionDataSource.map(item => (
              <SegmentedToggle.Button
                key={item.value}
                value={item.value}
                size={'small'}
                dataHook={item.dataHook}
                prefixIcon={item.icon}
              >
                {item.label}
              </SegmentedToggle.Button>
            ))}
          </SegmentedToggle>
        </FieldSet>
      </Box>
    </Panel>
  );
};
